            ["Sims the tab you see against the target and for the fight length at the top right: \"%s\" on Character, \"%s\" in the Planner, \"%s\" on Sets. While it sims, it stops it."] = "Просчитывает открытую вкладку против цели и с длительностью боя, заданными справа вверху: «%s» на вкладке «Персонаж», «%s» в «Планировщике», «%s» на вкладке «Наборы». Во время расчёта — останавливает его.",
            ["Simulate"] = "Просчитать",
            ["Simulator"] = "Симулятор",
            ["Skip tour"] = "Пропустить обзор",
            ["Slot"] = "Ячейка",
            ["Slots"] = "Ячейки",
            ["Smooth"] = "Плавно",
            ["Smooth: %d ms per frame, the game stays the smoothest."] = "Плавно: %d мс за кадр, игра остаётся самой плавной.",
            ["Sort: %s"] = "Сортировка: %s",
            ["Source"] = "Источник",
            ["Sources"] = "Источники",
            ["Spec"] = "Специализация",
            ["Spell Damage"] = "Урон от заклинаний",
            ["Spell Power"] = "Сила заклинаний",
            ["Spell crit · hit"] = "Крит · меткость заклинаний",
            ["Spirit"] = "Дух",
            ["Staff"] = "Посох",
            ["Stamina"] = "Выносливость",
            ["Standard (Percent)"] = "Стандарт (Проценты)",
            ["Star items to see which dungeons, bosses and rares to run."] = "Отметьте предметы звёздочкой, чтобы увидеть, какие подземелья, боссов и редких мобов стоит пройти.",
            ["Start from"] = "Начать с",
            ["Start the Best in Slot sim here: it builds your list from every item you can wear while you take the tour (a few minutes)."] = "Запустите здесь сим «Лучшее в слоте»: он составит ваш список из всех предметов, которые вы можете надеть, пока вы проходите обзор (несколько минут).",
            ["Start the tour"] = "Начать обзор",
            ["Starts the quest"] = "Начинает задание",
            ["Stat priority"] = "Приоритет характеристик",
            ["Stats for %s"] = "Характеристики: %s",
            ["Status"] = "Статус",
            ["Step %d of %d: %s"] = "Шаг %d из %d: %s",
            ["Still collecting, please wait for the result line."] = "Сбор ещё идёт, дождитесь строки с итогом.",
            ["Stop"] = "Стоп",
            ["Stopped."] = "Остановлено.",
            ["Strength"] = "Сила",
            ["Subtlety"] = "Скрытность",
            ["Survival"] = "Выживание",
            ["Switch it on for your Best in Slot set, the next upgrades, the simulator and the upgrade check for loot. The settings have it too (Modules)."] = "Включите его, чтобы видеть ваш комплект BiS, следующие улучшения, симулятор и проверку добычи на улучшение. Он есть и в настройках (Модули).",
            ["Switch off the pages you do not use. Best in Slot and Wishlist also take their marks, tooltip lines and alerts with them. One module always stays on."] = "Отключите страницы, которыми не пользуетесь. «Лучшее в слоте» и «Список желаний» убирают заодно свои отметки, строки в подсказках и оповещения. Один модуль всегда остаётся включённым.",
            ["Switch off what you do not use: its tab goes away, Best in Slot also takes its crowns and tooltip lines with it, Wishlist its stars, tooltip mark and alerts. One module always stays on. The database look has its own pages."] = "Отключите то, чем не пользуетесь: пропадёт его вкладка, «Лучшее в слоте» уберёт также короны и строки в подсказках, список желаний — звёзды, отметку в подсказке и оповещения. Один модуль всегда остаётся включённым. У вида «База данных» свои страницы.",
            ["Switch on Best in Slot"] = "Включить «Лучшее в слоте»",
            ["Sword"] = "Меч",
            ["TANK"] = "ТАНК",
            ["TURN IN"] = "СДАЧА",
            ["Tabard"] = "Гербовая накидка",
            ["Tailoring"] = "Портняжное дело",
            ["Taken from the English collect, not asked: %d items without data, %d refused quests."] = "Взято из английского сбора, без запросов: %d предметов без данных, %d отклонённых заданий.",
            ["Takes every item out of this set."] = "Убирает все предметы из этого набора.",
            ["Talents the sim plays itself: %s."] = "Таланты, которые симулятор учитывает сам: %s.",
            ["Tanks wear their heaviest armor."] = "Танки носят самую тяжёлую броню.",
            ["Target"] = "Цель",
            ["Teal"] = "Бирюзовый",
            ["The Best in Slot module is off (Modules)."] = "Модуль «Лучшее в слоте» отключён (Модули).",
            ["The Best in Slot sim is running: the small window shows how far it is. Take the tour meanwhile; your list is ready when it is done."] = "Сим «Лучшее в слоте» запущен: маленькое окно показывает, сколько готово. Пройдите пока обзор; ваш список будет готов, когда расчёт закончится.",
            ["The Journal module is off (Modules)."] = "Модуль «Журнал» отключён (Модули).",
            ["The Underbelly"] = "Клоака",
            ["The Wishlist module is off (Modules)."] = "Модуль «Список желаний» отключён (Модули).",
            ["The boss, rare or zone that drops it, with the chance."] = "Босс, редкий противник или зона, где он выпадает, с шансом.",
            ["The bosses and their loot are added as soon as they are seen in the game or revealed."] = "Боссы и их добыча появятся, как только их увидят в игре или раскроют.",
            ["The damage the sim found for the item against what you wear, or that it is on your Best in Slot list."] = "Урон, который сим нашёл для предмета против надетого, или что предмет в вашем списке BiS.",
            ["The dungeon entrances on the world map, the alert when a wishlist item drops and opening the dungeon you are in."] = "Входы в подземелья на карте мира, оповещение о выпавшем предмете из списка желаний и открытие подземелья, в котором вы находитесь.",
            ["The filter of your Best in Slot list: the spec it is made for, the armor it takes and where its items may come from. Open it any time: the first time it explains itself."] = "Фильтр вашего списка BiS: специализация, для которой он составлен, броня, которую он берёт, и откуда могут быть его предметы. Откройте его в любой момент: в первый раз он сам всё объяснит.",
            ["The filter of your Best in Slot list: the spec it is made for, the armor it takes and where its items may come from; its second tab orders your stats. Open it any time: the first time it explains itself."] = "Фильтр вашего списка BiS: специализация, для которой он составлен, броня, которую он берёт, и откуда могут быть его предметы; вторая вкладка упорядочивает ваши характеристики. Откройте его в любой момент: в первый раз он сам всё объяснит.",
            ["The game blocked an action of Lootified (%s). /lf errors shows the details."] = "Игра заблокировала действие Lootified (%s). Подробности: /lf errors.",
            ["The game does not let addons open the world map right now."] = "Игра сейчас не позволяет аддонам открывать карту мира.",
            ["The game does not let addons open the world map right now. The spot is marked: open your world map to see it."] = "Игра сейчас не позволяет аддонам открывать карту мира. Место отмечено: откройте карту мира, чтобы его увидеть.",
            ["The game has no data of this item yet: press Sim again in a moment."] = "У игры ещё нет данных об этом предмете: нажмите «Сим» ещё раз чуть позже.",
            ["The game has no map data for the open world mobs yet."] = "В игре пока нет данных карты для мобов открытого мира.",
            ["The game has no map position for this spot."] = "Для этого места в игре нет позиции на карте.",
            ["The game has not sent all of its data yet."] = "Игра ещё не прислала все данные.",
            ["The game is still loading your spell texts: try again in a moment."] = "Игра ещё загружает тексты заклинаний: попробуйте снова чуть позже.",
            ["The gear button at the top right opens the settings. Pick a category on the left; every change applies at once."] = "Кнопка с шестерёнкой справа вверху открывает настройки. Выберите категорию слева; каждое изменение применяется сразу.",
            ["The green arrow marks the items of your Best in Slot list (sort by For you to see the best first)."] = "Зелёная стрелка отмечает предметы вашего списка BiS (сортировка «Для вас» ставит лучшие первыми).",
            ["The green arrow marks the items of your Best in Slot list, with the damage they add (sort by For you to see the biggest first)."] = "Зелёная стрелка отмечает предметы вашего списка BiS и урон, который они добавят (сортировка «Для вас» ставит самые большие первыми).",
            ["The items you starred, grouped by where they drop. You get an alert as soon as one drops."] = "Отмеченные вами предметы, сгруппированные по источнику. Как только один из них выпадет, вы получите оповещение.",
            ["The items you starred; the stars, the tooltip mark and the alert when one drops."] = "Отмеченные вами предметы; звёзды, отметка в подсказке и оповещение, когда предмет выпадает.",
            ["The language is under Language; this tour starts again from Tour & help or with /lf tour. Found a bug or have an idea? Website & Discord are here and behind the ? at the top. Have fun!"] = "Язык меняется в разделе «Язык»; этот обзор снова запускается из «Обзор и помощь» или командой /lf tour. Нашли ошибку или есть идея? Сайт и Discord — здесь и под значком ? вверху. Удачи!",
            ["The language of the interface and of the game's names in Lootified."] = "Язык интерфейса и игровых названий в Lootified.",
            ["The last collect was cut off: what it had read is kept. /lf collect again reads the rest."] = "Последний сбор был прерван: прочитанное сохранено. Новый /lf collect прочитает остальное.",
            ["The level of the target dummy. It stands still, never hits back and is hit from behind."] = "Уровень тренировочного манекена. Он стоит на месте, не бьёт в ответ, удары наносятся со спины.",
            ["The lines Lootified adds to item tooltips, one switch each. The preview shows a real tooltip as you set it."] = "Строки, которые Lootified добавляет в подсказки предметов, у каждой свой переключатель. Предпросмотр показывает настоящую подсказку с вашими настройками.",
            ["The list of the first start: every armor your class wears, quests, dungeons and rares, drops of 10 % or more."] = "Список первого запуска: вся броня вашего класса, задания, подземелья и редкие мобы, добыча с шансом от 10 %.",
            ["The loot of the dungeons' and raids' bosses and trash."] = "Добыча боссов и обычных противников подземелий и рейдов.",
            ["The loot of the open world's rares and other mobs that carry the item."] = "Добыча редких и других мобов открытого мира, у которых есть этот предмет.",
            ["The picked item: its stats and where it drops (click a mob or a quest to open it)."] = "Выбранный предмет: характеристики и откуда он выпадает (нажмите на моба или задание, чтобы открыть их).",
            ["The picked item: its stats, where it drops (click a mob or a quest to open it) and the wishlist button. You get an alert when a wishlist item drops."] = "Выбранный предмет: характеристики, откуда он выпадает (нажмите на моба или задание, чтобы открыть их), и кнопка списка желаний. Когда выпадет предмет из списка желаний, вы получите оповещение.",
            ["The quests that give the item or need it."] = "Задания, которые дают предмет или требуют его.",
            ["The rares and mobs of every zone with their drops and camps."] = "Редкие противники и обычные монстры каждой зоны с добычей и местами появления.",
            ["The rares and other mobs of every zone with their drops, drop chances and camps on the map. The page shows the zone you are in."] = "Редкие и другие мобы каждой зоны с добычей, шансами выпадения и лагерями на карте. Страница показывает зону, в которой вы находитесь.",
            ["The same for bosses and rares, for quests (with their chains) and for dungeons, raids and zones. Links between the pages open the right entry."] = "То же самое для боссов и редких мобов, для заданий (с цепочками) и для подземелий, рейдов и зон. Ссылки между страницами открывают нужную запись.",
            ["The set fights in the simulator's planner for its exact damage: the number on the sheet is an estimate from each item simmed alone."] = "Набор сражается в планировщике симулятора, чтобы узнать точный урон: число на листе — оценка по предметам, просимулированным по отдельности.",
            ["The simulator could not read your character: %s"] = "Симулятору не удалось прочитать персонажа: %s",
            ["The simulator fights with your talents and gear and shows every upgrade in DPS. You run the sims yourself (the Best in Slot sim takes a few minutes): pick it only if you want that."] = "Симулятор сражается с вашими талантами и экипировкой и показывает каждое улучшение в DPS. Симы вы запускаете сами (сим «Лучшее в слоте» занимает несколько минут): выбирайте, только если вам это нужно.",
            ["The simulator has no numbers for this item."] = "У симулятора нет данных для этого предмета.",
            ["The simulator is calculating"] = "Симулятор считает",
            ["The simulator rates your damage. Your upgrades follow your stat weights."] = "Симулятор оценивает ваш урон. Улучшения подбираются по весам ваших характеристик.",
            ["The simulator stopped: %s"] = "Симулятор остановился: %s",
            ["The target: %s"] = "Цель: %s",
            ["The tour stopped because of combat. /lf tour starts it again."] = "Обзор остановлен из-за боя. Команда /lf tour запустит его снова.",
            ["These are the bosses, numbered in their order. Click one to see its loot next to the map; click it again to close it."] = "Это боссы, пронумерованные по порядку. Нажмите на босса, чтобы увидеть его добычу рядом с картой; повторный клик закрывает её.",
            ["This decides how this character's upgrades show in tooltips, loot rolls, For you and its Best in Slot list."] = "От этого зависит, как улучшения этого персонажа показываются в подсказках, при розыгрыше добычи, в «Для вас» и в его списке BiS.",
            ["This dungeon has more than one floor: switch between them here. Next to the buttons is the name of the floor you see."] = "В этом подземелье несколько этажей: переключайтесь между ними здесь. Рядом с кнопками — название этажа, который вы видите.",
            ["This is For you, your start page: the dungeons for your level with your upgrades and your next Best in Slot items. Click anything to open it."] = "Это «Для вас», ваша стартовая страница: подземелья для вашего уровня с улучшениями и следующие предметы BiS. Нажмите на что угодно, чтобы открыть.",
            ["This is For you, your start page: the dungeons for your level. Click anything to open it."] = "Это «Для вас», ваша стартовая страница: подземелья для вашего уровня. Нажмите на что угодно, чтобы открыть.",
            ["This item is not in the loot data. It may be crafted, sold by a vendor or come from a source that is new in Forever."] = "Этого предмета нет в данных о добыче. Возможно, его изготавливают, продают торговцы или он берётся из нового источника в Forever.",
            ["This item is not in your game client yet (datamined / upcoming)."] = "Этого предмета ещё нет в вашем клиенте (из датамайна / скоро появится).",
            ["This spec fights in Bear Form, which druids learn at level 10. Until then, pick another spec on the Best in Slot sheet."] = "Эта специализация сражается в облике медведя, который друиды изучают на 10-м уровне. До тех пор выберите другую специализацию на странице BiS.",
            ["This spec fights in Cat Form, which druids learn at level 20. Until then, pick another spec on the Best in Slot sheet."] = "Эта специализация сражается в облике кошки, который друиды изучают на 20-м уровне. До тех пор выберите другую специализацию на странице BiS.",
            ["This spec fights in Defensive Stance, which warriors learn at level 10. Until then, pick another spec on the Best in Slot sheet."] = "Эта специализация сражается в оборонительной стойке, которую воины изучают на 10-м уровне. До тех пор выберите другую специализацию на странице BiS.",
            ["This spec fights with a pet, which hunters get at level 10. Until then, pick another spec on the Best in Slot sheet."] = "Эта специализация сражается вместе с питомцем, которого охотники получают на 10-м уровне. До тех пор выберите другую специализацию на странице BiS.",
            ["This spec tanks with a shield: put one on, then try again."] = "Эта специализация танкует со щитом: наденьте щит и попробуйте снова.",
            ["This tour shows every part of Lootified. At the end you see the settings, where you can switch off what you do not need."] = "Этот обзор показывает все части Lootified. В конце вы увидите настройки, где можно отключить то, что вам не нужно.",
            ["Thrown"] = "Метательное оружие",
            ["Tooltips"] = "Подсказки",
            ["Totem"] = "Тотем",
            ["Tour & help"] = "Обзор и помощь",
            ["Trade Goods (Parts)"] = "Хозяйственные товары (детали)",
            ["Trash"] = "Трэш",
            ["Trash & zone drops"] = "Трэш и добыча в зоне",
            ["Trash mobs"] = "Трэш-мобы",
            ["Trinket"] = "Аксессуар",
            ["Try on"] = "Примерить",
            ["Try on set (Dressing Room)"] = "Примерить комплект (примерочная)",
            ["Try the name of a dungeon, boss, quest, zone, mob or item. Parts of words work too, e.g. \"vanc\" or \"blade\"."] = "Введите название подземелья, босса, задания, зоны, моба или предмета. Подходят и части слов, например «ван» или «клинок».",
            ["Turbo"] = "Турбо",
            ["Turbo: %d ms per frame, the sim is done soonest, the game can run slower meanwhile."] = "Турбо: %d мс за кадр, сим закончит быстрее всего, а игра пока может идти медленнее.",
            ["Turn in"] = "Сдача",
            ["Two sets of your own: click a slot to pick any item your character can put on there, or drop an item from your bags on it. The set fights on its own."] = "Два ваших набора: нажмите на ячейку и выберите любой предмет, который персонаж может туда надеть, или перетащите предмет из сумок. Набор сражается сам по себе.",
            ["Two-Hand"] = "Двуручное",
            ["Two-hand weapon"] = "Двуручное оружие",
            ["Two-hander in the main hand"] = "Двуручное оружие в правой руке",
            ["Type"] = "Тип",
            ["Type /lf collect stop to cancel. Please stay logged in."] = "Отмена: /lf collect stop. Пожалуйста, не выходите из игры.",
            ["Type /reload, then send the file WTF\\Account\\<account>\\SavedVariables\\Lootified.lua."] = "Введите /reload, затем отправьте файл WTF\\Account\\<аккаунт>\\SavedVariables\\Lootified.lua.",
            ["Type a name, a slot or a place: the list follows as you type. The switch beside it and Sort change what shows and in which order."] = "Введите название, ячейку или место — список обновляется по мере ввода. Переключатель рядом и сортировка меняют, что показано и в каком порядке.",
            ["Type at least 3 letters"] = "Введите хотя бы 3 буквы",
            ["Uncommon"] = "Необычный",
            ["Unknown"] = "Неизвестно",
            ["Up to date"] = "Актуально",
            ["Upgrade"] = "Улучшение",
            ["Upgrade check for loot"] = "Проверка добычи на улучшение",
            ["Upgrade for my spec"] = "Улучшение для моей специализации",
            ["Upgrade for you"] = "Улучшение для вас",
            ["Upgrade for you: %s"] = "Улучшение для вас: %s",
            ["Upgrades for you"] = "Улучшения для вас",
            ["Upgrades only"] = "Только улучшения",
            ["Usable by me"] = "Подходит мне",
            ["Usable from level %d"] = "Можно использовать с %d ур.",
            ["Usage: /lf collect, /lf collect language, /lf collect stop or /lf collect clear."] = "Использование: /lf collect, /lf collect language, /lf collect stop или /lf collect clear.",
            ["Use %d %s"] = "Использовать (%d): %s",
            ["Use Advanced"] = "Выбрать «Расширенный»",
