            ["WORLD DROP"] = "ДОБЫЧА В МИРЕ",
            ["Waist"] = "Пояс",
            ["Wand"] = "Жезл",
            ["Warlock"] = "Чернокнижник",
            ["Warrior"] = "Воин",
            ["Weapon skill"] = "Навык оружия",
            ["Weapons"] = "Оружие",
            ["Website & Discord"] = "Сайт и Discord",
            ["Welcome to Lootified"] = "Добро пожаловать в Lootified",
            ["Welcome to Lootified! How should the window look?"] = "Добро пожаловать в Lootified! Как должно выглядеть окно?",
            ["Welcome to the Database"] = "Добро пожаловать в базу данных",
            ["What I wear"] = "Надетое",
            ["What is collected so far is saved with the next /reload."] = "Собранное сохранится при следующем /reload.",
